UPDATE router_wallet
SET balance_units = balance_units + #{amountUnits},
    updated_at = CURRENT_TIMESTAMP(3)
WHERE user_id = #{userId}
AND #{amountUnits} > 0
AND balance_units <= 9223372036854775807 - #{amountUnits}

UPDATE router_wallet
SET balance_units = balance_units - #{amountUnits},
    frozen_units = frozen_units + #{amountUnits},
    updated_at = CURRENT_TIMESTAMP(3)
WHERE user_id = #{userId}
AND #{amountUnits} > 0
AND balance_units >= #{amountUnits}
AND frozen_units <= 9223372036854775807 - #{amountUnits}

UPDATE router_wallet
SET balance_units = balance_units + #{amountUnits},
    frozen_units = frozen_units - #{amountUnits},
    updated_at = CURRENT_TIMESTAMP(3)
WHERE user_id = #{userId}
AND #{amountUnits} > 0
AND frozen_units >= #{amountUnits}
AND balance_units <= 9223372036854775807 - #{amountUnits}
